import Foundation

public struct APIKeysDictatorSection: Codable, Sendable, Equatable
{
    public let openai_api_key: String

    public init(openai_api_key: String = "")
    {
        self.openai_api_key = openai_api_key
    }
}

public struct APIKeysFile: Codable, Sendable, Equatable
{
    public let dictator: APIKeysDictatorSection?

    public init(dictator: APIKeysDictatorSection? = nil)
    {
        self.dictator = dictator
    }
}

public struct APIKeysStore: SecretStore, Sendable
{
    public let fileURL: URL

    public init(fileURL: URL = Self.defaultFileURL())
    {
        self.fileURL = fileURL
    }

    public static func defaultFileURL(
        currentDirectoryPath: String = FileManager.default.currentDirectoryPath,
        fileManager: FileManager = .default
    ) -> URL
    {
        let cwd = URL(fileURLWithPath: currentDirectoryPath, isDirectory: true)
        if let repoRoot = SheafRootDiscovery.findRepoRoot(startingAt: cwd, fileManager: fileManager)
        {
            return repoRoot.appendingPathComponent("config/api_keys.json", isDirectory: false)
        }

        return cwd.appendingPathComponent("config/api_keys.json", isDirectory: false)
    }

    public static func defaultExampleFileURL(
        currentDirectoryPath: String = FileManager.default.currentDirectoryPath,
        fileManager: FileManager = .default
    ) -> URL
    {
        let cwd = URL(fileURLWithPath: currentDirectoryPath, isDirectory: true)
        if let repoRoot = SheafRootDiscovery.findRepoRoot(startingAt: cwd, fileManager: fileManager)
        {
            return repoRoot.appendingPathComponent("config/api_keys.example.json", isDirectory: false)
        }

        return cwd.appendingPathComponent("config/api_keys.example.json", isDirectory: false)
    }

    public func load() throws -> APIKeysFile?
    {
        guard FileManager.default.fileExists(atPath: fileURL.path) else
        {
            return nil
        }

        do
        {
            let data = try Data(contentsOf: fileURL)
            return try JSONDecoder().decode(APIKeysFile.self, from: data)
        }
        catch
        {
            throw DictatorError.configUpdateFailed("invalid API keys file: \(error)")
        }
    }

    public func getOpenAIKey() throws -> String?
    {
        guard let loaded = try load() else
        {
            return nil
        }

        return APIKeyResolver.resolve
        {
            loaded.dictator?.openai_api_key
        }
    }

    public func setOpenAIKey(_ key: String) throws
    {
        _ = key
        throw DictatorError.configUpdateFailed("API keys file is read-only")
    }

    public func clearOpenAIKey() throws
    {
        throw DictatorError.configUpdateFailed("API keys file is read-only")
    }
}

import XCTest
@testable import DictatorService

final class TraceLoggerTests: XCTestCase
{
    func testConfigureWritesUnderLogsDictatorDirectory() throws
    {
        let tempDir = try makeTempDir()
        defer { try? FileManager.default.removeItem(at: tempDir) }

        let logDirectory = tempDir.appendingPathComponent("logs/dictator", isDirectory: true).path
        TraceLogger.configure(logDirectoryPath: logDirectory)
        TraceLogger.reset()
        TraceLogger.log("trace logger test message")

        let logFile = tempDir
            .appendingPathComponent("logs/dictator/trace.log", isDirectory: false)

        XCTAssertTrue(FileManager.default.fileExists(atPath: logFile.path))

        let contents = try String(contentsOf: logFile, encoding: .utf8)
        XCTAssertTrue(contents.contains("trace logger test message"))
        XCTAssertFalse(contents.contains("sk-"))
    }

    func testConfigureForRepoRootUsesLogsDictator() throws
    {
        let repoRoot = try makeTempDir()
        defer { try? FileManager.default.removeItem(at: repoRoot) }

        TraceLogger.configureForRepoRoot(repoRoot)
        TraceLogger.reset()
        TraceLogger.log("repo-root trace")

        let logFile = repoRoot
            .appendingPathComponent("logs/dictator/trace.log", isDirectory: false)

        XCTAssertTrue(FileManager.default.fileExists(atPath: logFile.path))
        let contents = try String(contentsOf: logFile, encoding: .utf8)
        XCTAssertTrue(contents.contains("repo-root trace"))
    }

    private func makeTempDir() throws -> URL
    {
        let base = FileManager.default.temporaryDirectory
        let dir = base.appendingPathComponent(UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }
}

import XCTest
@testable import DictatorCore

final class SheafRuntimePathsTests: XCTestCase
{
    func testBootstrapDefaultsUseSheafPaths() {
        let bootstrap = RuntimeConfigFile.bootstrap()

        XCTAssertEqual(bootstrap.dataDir, "data/dictator")
        XCTAssertEqual(bootstrap.systemPromptsDir, "projects/dictator/src/prompts/system-prompts")
        XCTAssertEqual(bootstrap.dictatorServerPort, 9003)
        XCTAssertTrue(bootstrap.dictatorServerEnabled)
    }

    func testDefaultConfigFileURLPointsAtConfigDictatorJSON() throws
    {
        let repoRoot = try makeSheafRepoRoot()
        defer { try? FileManager.default.removeItem(at: repoRoot) }

        let nested = repoRoot.appendingPathComponent("projects/dictator", isDirectory: true)
        let fileURL = RuntimeConfigStore.defaultFileURL(currentDirectoryPath: nested.path)

        XCTAssertEqual(
            fileURL.standardizedFileURL.path,
            repoRoot.appendingPathComponent("config/dictator.json").standardizedFileURL.path
        )
    }

    func testResolvedDataDirectoryUsesRepoRootForDataDictatorPath() throws
    {
        let repoRoot = try makeSheafRepoRoot()
        defer { try? FileManager.default.removeItem(at: repoRoot) }

        let runtime = RuntimeConfigFile(
            version: 2,
            cloudModel: "gpt-4.1-mini",
            localModel: "qwen2.5:7b-instruct",
            useCloud: false,
            dataDir: "data/dictator",
            updatedAt: "2026-06-07T00:00:00Z"
        )

        let nested = repoRoot.appendingPathComponent("projects/dictator", isDirectory: true).path
        let resolved = runtime.resolvedDataDirectoryURL(currentDirectoryPath: nested)

        XCTAssertEqual(
            resolved.standardizedFileURL.path,
            repoRoot.appendingPathComponent("data/dictator", isDirectory: true).standardizedFileURL.path
        )
    }

    func testResolvedSystemPromptsDirectoryUsesRepoRootPath() throws
    {
        let repoRoot = try makeSheafRepoRoot()
        defer { try? FileManager.default.removeItem(at: repoRoot) }

        let promptsDir = repoRoot.appendingPathComponent(
            "projects/dictator/src/prompts/system-prompts",
            isDirectory: true
        )
        try FileManager.default.createDirectory(at: promptsDir, withIntermediateDirectories: true)

        let runtime = RuntimeConfigFile(
            version: 2,
            cloudModel: "gpt-4.1-mini",
            localModel: "qwen2.5:7b-instruct",
            useCloud: false,
            systemPromptsDir: "projects/dictator/src/prompts/system-prompts",
            updatedAt: "2026-06-07T00:00:00Z"
        )

        let nested = repoRoot.appendingPathComponent("projects/dictator", isDirectory: true).path
        let resolved = runtime.resolvedSystemPromptsDirectoryURL(currentDirectoryPath: nested)

        XCTAssertEqual(resolved.standardizedFileURL.path, promptsDir.standardizedFileURL.path)
    }

    private func makeSheafRepoRoot() throws -> URL
    {
        let repoRoot = try makeTempDir()
        try FileManager.default.createDirectory(
            at: repoRoot.appendingPathComponent("config", isDirectory: true),
            withIntermediateDirectories: true
        )
        try FileManager.default.createDirectory(
            at: repoRoot.appendingPathComponent("projects/dictator", isDirectory: true),
            withIntermediateDirectories: true
        )
        try """
        []
        """.write(
            to: repoRoot.appendingPathComponent("config/services.json"),
            atomically: true,
            encoding: .utf8
        )
        return repoRoot
    }

    private func makeTempDir() throws -> URL
    {
        let base = FileManager.default.temporaryDirectory
        let dir = base.appendingPathComponent(UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }
}

